class FeedSerializer
  def initialize(posts)
    @posts = posts
  end

  def as_json(*)
    @posts.map do |post|
      {
        id: post.id,
        title: post.title,
        author_name: post.author.name,
        author_avatar: post.author.avatar_url,
        comment_count: post.comments.count
      }
    end
  end
end

class FeedSerializer
  def initialize(posts)
    @posts = posts.includes(:author).with_attached_cover
  end

  def as_json(*)
    @posts.map do |post|
      { id: post.id, title: post.title, author_name: post.author.name, comments: post.comments_count }
    end
  end
end

