def index
  @teams = current_account.teams.order(:name)
  @open_counts = Ticket.where(team_id: @teams.select(:id), status: "open").group(:team_id).count
  @rows = @teams.map { |team| [team, @open_counts.fetch(team.id, 0)] }
end

